  'Vila': 'قرية',
  'Volume do soundboard (só para você): {quanto}%': 'مستوى لوحة الأصوات (لك وحدك): {quanto}%',
  'Voz bem mais grave e pesada.': 'صوت أعمق وأثقل بكثير.',
  'Voz espremida e chiada, como a do piloto no rádio.': 'صوت مضغوط وفيه خشخشة، كصوت الطيار في اللاسلكي.',
