  'Lobisomem': 'مستذئب',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'في الليل، يُختار مع المستذئبين الآخرين مَن سيتعرض للهجوم. وفي النهار، المهم ألا يشكّ أحد.',
  'Vidente': 'البصيرة',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'في الليل، يمكن كشف ما إذا كان أحدهم مستذئبًا. وفي النهار يمكن البوح بذلك، إن كان الأمر يستحق المخاطرة.',
  'Anjo': 'ملاك',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'في الليل، يُختار شخص لحمايته. إذا هاجمه المستذئبون، يفشل الهجوم.',
  'Da vila': 'من القرية',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'في الليل: النوم. وفي النهار: كشف المستذئبين والتصويت لإخراجهم من اللعبة.',
  'A vila venceu!': 'فازت القرية!',
  'Os lobisomens venceram!': 'فاز المستذئبون!',
