  'Os lobisomens atacaram {nome} durante a noite.': 'هاجم المستذئبون {nome} أثناء الليل.',
  'Ninguém morreu esta noite.': 'لم يمت أحد هذه الليلة.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'اليوم {n}. حان وقت النقاش والتصويت على من يُظن أنه مستذئب.',
  'A vila tirou {nome} do jogo.': 'أخرجت القرية {nome} من اللعبة.',
  'Empate: ninguém sai hoje.': 'تعادل: لا أحد يخرج اليوم.',
  'Clique em quem os lobisomens vão atacar.': 'يمكن النقر على مَن سيهاجمه المستذئبون.',
  'Você já usou a sua visão esta noite.': 'استُخدمت رؤيا هذه الليلة بالفعل.',
  'Clique em alguém para descobrir se é lobisomem.': 'يمكن النقر على أحد المشاركين لمعرفة ما إذا كان مستذئبًا.',
  'Clique em quem você quer proteger esta noite.': 'يمكن النقر على مَن تُراد حمايته هذه الليلة.',
  'Durma. Os outros papéis estão agindo.': 'وقت النوم. الأدوار الأخرى تعمل الآن.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'انتهى دورك في اللعبة. من الآن مشاهدة فقط — دون البوح بشيء!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'يمكن النقر على مَن يُراد إخراجه من اللعبة. يخرج صاحب أكثر الأصوات؛ وعند التعادل لا يخرج أحد.',
