  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'يحصل كل مشارك على دور سري. في الليل يهاجم المستذئبون؛ وفي النهار تتحاور القرية وتصوّت على من يخرج من اللعبة. يلزم 4 أشخاص أو أكثر.',
