  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': 'تمت إزالة {tipo} «{item}» ({onde}) من Syden بناءً على مطالبة بالحقوق من {quem}. إذا كان لديك إذن بالنشر، يمكنك الرد هنا وشرح الأمر: سيؤخذ ردك في الاعتبار. وإلى أن يتضح ذلك، يبقى المحتوى محذوفًا. توضح الشروط كيف يعمل ذلك، في القسم 4: https://syden.chat/termos.html#direito-autoral',
