  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'لم يصل خلال بضع دقائق؟ يُرجى التحقق من مجلد الرسائل غير المرغوب فيها أو العروض الترويجية. وإن لم يكن هناك، يمكن إرساله مرة أخرى.',
