  'Setas para dirigir, Espaço para derrapar e carregar o turbo.': 'الأسهم للتوجيه، ومفتاح المسافة للانزلاق وشحن التوربو.',
  'Seu recorde: {tempo}': 'رقمك القياسي: {tempo}',
