  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'خمس جولات من الألعاب السريعة، كلٌّ على شاشته: سرعة البديهة والتصويب والذاكرة وحدّة النظر. الأفضل في كل جولة ينال نقاطًا أكثر.',
  'Saque rápido': 'السحب السريع',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'المطلوب انتظار الإشارة ثم الضغط بأسرع ما يمكن. الضغط قبل الإشارة يعني الخروج.',
  'Medidor de força': 'مقياس القوة',
  'Pare a barra o mais perto possível de 100%.': 'المطلوب إيقاف الشريط في أقرب نقطة ممكنة من 100%.',
  'Parar o relógio': 'إيقاف الساعة',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'المطلوب إيقاف الساعة عند 10 ثوانٍ بالضبط. تختفي الأرقام بعد 3.',
  'Jogo dos copos': 'لعبة الأكواب',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'المطلوب متابعة مكان الجزرة وتتبّع الكوب. الإصابة الأسرع تساوي أكثر.',
  'Siga o coelho': 'تتبُّع الأرنب',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'المطلوب تكرار الأسهم بالترتيب. مع كل إصابة يُضاف سهم آخر.',
  'Tiro ao alvo': 'الرماية على الهدف',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'المطلوب إصابة الأهداف التي تظهر. كل هدف بنقطة.',
