  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'القفز من الأرجوحة للهبوط على ورقة. الأبعد يساوي أكثر.',
  'Barraca de tiro': 'كشك الرماية',
  'Acerte os corvos que passarem. No coelhinho, não!': 'إصابة الغربان المارّة. أما الأرنب الصغير فلا!',
  'Brasas da fogueira': 'جمر النار',
  'Desvie das brasas. São só três corações!': 'تفادي الجمر. ثلاثة قلوب فقط!',
  'Cabo de guerra': 'شدّ الحبل',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'الضغط على السهم الظاهر لشدّ الحبل. الخطأ يُجمِّد!',
  'Canteiro que encolhe': 'الحوض الذي ينكمش',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'دفع الآخرين خارج الحوض. الحافة الوامضة ستسقط!',
  'Corrida de cavalinho': 'سباق الأحصنة الخشبية',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'التبديل بين ← و → بإيقاع. مع العجلة الزائدة ينقطع النفَس.',
  'Cartas do celeiro': 'بطاقات الحظيرة',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'في الدور: قلب بطاقة أو الاحتفاظ بالجزر. الثعلب يأخذ كل شيء!',
  'Chuva de cenouras': 'مطر الجزر',
  'Desça pegando as cenouras. Das pedras, fuja!': 'النزول مع التقاط الجزر. والهروب من الحجارة!',
  'De galho em galho': 'من غصن إلى غصن',
  'Solte o cipó quando ele estiver na faixa clara.': 'إفلات الكرمة حين تكون في الشريط الفاتح.',
  'Colheita em dupla': 'حصاد ثنائي',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'ضمن ثنائي: من على الغصن يُسقط الفراولة الناضجة، ومن في الأسفل يلتقطها بالسلة.',
  'Baile da toca': 'رقصة الجحر',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'حفظ ترتيب الرقص. في النهاية، تحديد من رقص على المصباح المحدَّد.',
  'Chão que desmorona': 'الأرض المنهارة',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'اللوح يتشقق حين يقف عليه أحد. المشي دون توقف ودفع الآخرين إلى الماء!',
  'Arrume a despensa': 'ترتيب المؤونة',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'حفظ مكان كل برطمان وإعادة الجميع إلى أماكنها.',
  'Esconde-esconde na horta': 'الغميضة في الحديقة',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'الاختباء حيث لن ينظر الفانوس. حامل الفانوس هو الباحث!',
  'Três flechas': 'ثلاثة سهام',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'السهم يصعد مستقيمًا ويثقب ما يصادفه. البالونات الصغيرة تساوي أكثر.',
  'Bate quando der a flor': 'ضربة الزهرة',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'الضرب عند ظهور الزهرة المطابقة لزهرة المربع. على الصورة الخطأ، خروج من اللعبة.',
  'Foguete de cenoura': 'صاروخ الجزر',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'الضخ حين تضيء الحلقة. خارج الإيقاع يتسرّب الهواء.',
  'Pegue a galinha': 'الإمساك بالدجاجة',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'محاصرة الدجاجة. حين تتعب تبطؤ.',
  'Repolhos no gelo': 'ملفوف على الجليد',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'التقاط الجزر على الجليد والهروب من الملفوف.',
  'Abóboras ladeira abaixo': 'اليقطين المتدحرج',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'من الأعلى يتدحرج اليقطين؛ ومن يصعد يغيّر المسار للهروب منه!',
  'Quem está atrás da turma?': 'من يختبئ خلف الجماعة؟',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'اكتشاف المختبئ. فرصة واحدة فقط: كلما كان أبكر، زادت القيمة.',
  'Arremesso do nabo': 'رمي اللفت',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'الإفلات حين يشير اللفت إلى الملعب. كلما زاد الدوران، ذهب أبعد.',
  'Onda no açude': 'موجة في البركة',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'من على المجداف يرسل الأمواج؛ ومن على الطوف يقفز في اللحظة المناسبة!',
  'Pula o ponteiro': 'القفز فوق العقرب',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'القفز حين يمرّ العقرب. يزداد سرعة باستمرار.',
  'Ponte do riacho': 'جسر الجدول',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'نقل الألواح الثلاثة إلى الجسر. الحذر من الحجارة التي تغرق!',
  'Quem está em qual toca?': 'من في أي جحر؟',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'تتبّع الحيوانات من جحر إلى جحر. في النهاية، الإشارة إلى مكان صاحب البالون.',
  'As chaves da porteira': 'مفاتيح البوابة',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'أخذ جزرة ذهبية وحملها إلى البوابة. ينقص واحدة: دفع من يحملها!',
  'Destampe os potes': 'فتح البرطمانات',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'تدوير كل غطاء نحو جهة السهم، بسرعة. الجهة الخطأ تشدّه من جديد.',
  'Praga na toca': 'آفة في الجحر',
