  'O que dá para fazer com os móveis do seu quarto?': 'ماذا يمكن فعله بأثاث الغرفة؟',
  'Vender': 'البيع',
  'Plantar': 'الزراعة',
  'Arrumar como quiser': 'الترتيب حسب الرغبة',
  'Quiz relâmpago': 'مسابقة خاطفة',
  'Escolha a resposta certa antes que o tempo acabe.': 'اختيار الإجابة الصحيحة قبل انتهاء الوقت.',
  'Balsa a dois': 'طوف لاثنين',
  'Cada um rema de um lado: a remada empurra a balsa para o outro. Juntos, ela vai para a frente. Peguem as cenouras!': 'كلٌّ يجدّف من جهة: التجديف يدفع الطوف نحو الجهة الأخرى. معًا يتقدّم إلى الأمام. هيا لالتقاط الجزر!',
  'Retrato do coelho': 'صورة الأرنب',
  'Pare cada faixa com o retrato no lugar, de cima para baixo.': 'إيقاف كل شريط والصورة في مكانها، من الأعلى إلى الأسفل.',
  'Revezamento do riacho': 'تتابع الجدول',
  'Reme alternando ◀ e ▶ quando o remo estiver com você.': 'التجديف بالتناوب بين ◀ و ▶ حين يصل المجداف.',
  'Fuga do rio': 'الهروب من النهر',
  'Aperte sem parar para nadar. Quando vier um tronco, mergulhe!': 'الضغط دون توقف للسباحة. وعند مجيء جذع، الغوص!',
  'Roda da feira': 'عجلة السوق',
  'Aperte para a roda frear. Ela sempre desliza um pouco antes de parar.': 'الضغط لكبح العجلة. تنزلق دائمًا قليلًا قبل أن تتوقف.',
  'Uma tacada só': 'ضربة واحدة',
  'Prenda a mira, depois a força. Quem parar mais perto da toca ganha.': 'تثبيت التصويب، ثم القوة. الأقرب إلى الجحر يفوز.',
  'Tambor da turma': 'طبل الجماعة',
  'Ouça, repita a batida no mesmo ritmo e acrescente uma no fim.': 'الاستماع، ثم تكرار الإيقاع نفسه وإضافة ضربة في النهاية.',
  'Torta de cenoura': 'فطيرة الجزر',
  'Coma a torta com a sua dupla, alternando ◀ e ▶. Quem acabar primeiro ganha!': 'أكل الفطيرة مع الشريك، بالتناوب بين ◀ و ▶. أول من ينتهي يفوز!',
  'Trinca da horta': 'ثلاثية الحديقة',
  'Pare os três rolos na mesma figura. Cada trinca vale um ponto.': 'إيقاف البكرات الثلاث على الصورة نفسها. كل ثلاثية بنقطة.',
  'Vidas': 'الأرواح',
  'Cenoura teleguiada': 'جزرة موجَّهة',
  'Pronta': 'جاهزة',
  'No ar': 'في الجو',
  'Frear': 'فرملة',
  'Caiu! Agora é torcer de longe.': 'سقوط! الآن التشجيع من بعيد.',
  'Segure e solte: cenoura teleguiada': 'الضغط ثم الإفلات: جزرة موجَّهة',
  'Dois acertos você aguenta; o terceiro derruba. Curva fechada perto da cerca protege por um instante.': 'يمكن تحمّل إصابتين؛ الثالثة تُسقط. المنعطف الحاد قرب السياج يحمي للحظة.',
  'Acertos: {n}': 'الإصابات: {n}',
  'Pilotar (para trás, freia e dá ré)': 'القيادة (إلى الخلف: فرملة ورجوع)',
  'O barco desliza: tire o pé antes da curva. As argolas laranja dão um empurrão.': 'القارب ينزلق: رفع القدم قبل المنعطف. الحلقات البرتقالية تعطي دفعة.',
  'A toupeira-rei caiu!': 'سقط الخلد الملك!',
  'A turma caiu.': 'سقطت الجماعة.',
  'Dano da turma: {n}': 'ضرر الجماعة: {n}',
  'Sem vidas: agora é torcer pela turma.': 'لا أرواح: الآن التشجيع للجماعة.',
  'Fase {n} de {total}': 'المرحلة {n} من {total}',
  'Torrão na mão!': 'كتلة طين في اليد!',
  'Bomba de semente pronta': 'قنبلة البذور جاهزة',
  'Atirar o torrão': 'رمي كتلة الطين',
  'Bomba de semente': 'قنبلة البذور',
  'Fuja das marcas no chão. Passe por cima de um torrão azulado para pegá-lo e atire de volta na toupeira; a bomba de semente é uma por fase.': 'الهروب من العلامات على الأرض. المرور فوق كتلة طين مزرقّة لالتقاطها ورميها على الخلد؛ قنبلة البذور واحدة في كل مرحلة.',
  'Suba até o cata-vento. O que cai e os corvos levam de volta ao último andar.': 'الصعود حتى دوّارة الرياح. السقوط والغربان يعيدان إلى الطابق الأخير.',
  'Subir contra': 'الصعود ضد',
  'Nenhum amigo subiu esta torre ainda.': 'لم يصعد أي صديق هذا البرج بعد.',
  'Escolher a torre': 'اختيار البرج',
  'Esta subida já tinha começado quando você abriu: você assiste.': 'كان هذا الصعود قد بدأ عند الفتح: الوضع مشاهدة.',
  'Suba o celeiro por tábuas, fardos e vigas que se mexem até o cata-vento lá no alto, desviando das ferramentas que caem e dos corvos. No Solo, contra o relógio e os fantasmas dos amigos.': 'صعود الحظيرة عبر الألواح وبالات القش والعوارض المتحركة حتى دوّارة الرياح في الأعلى، مع تفادي الأدوات المتساقطة والغربان. في الفردي: ضد الساعة وأشباح الأصدقاء.',
  'Coelhos em teco-tecos sobre a horta, atirando ervilhas e uma cenoura teleguiada de cada vez. Dois acertos dá para aguentar; o terceiro derruba. O último no ar ganha.': 'أرانب في طائرات صغيرة فوق الحديقة، تطلق البازلاء وجزرة موجَّهة واحدة في كل مرة. يمكن تحمّل إصابتين؛ الثالثة تُسقط. آخر من يبقى في الجو يفوز.',
  'A turma inteira contra a toupeira-rei, que sai das tocas em três fases. Fuja das marcas no chão, pegue os torrões azulados e atire de volta. Ganha a turma, ou ninguém.': 'الجماعة كلها ضد الخلد الملك، الذي يخرج من الجحور في ثلاث مراحل. الهروب من العلامات على الأرض، والتقاط كتل الطين المزرقّة ورميها عليه. تفوز الجماعة، أو لا أحد.',
  'Corrida de barquinhos no lago, no riacho e no mangue. A água desliza: tire o pé antes da curva, cuidado com a margem e aproveite a correnteza e as argolas. No Solo, contra o relógio e os fantasmas dos amigos.': 'سباق قوارب صغيرة في البحيرة والجدول والمانغروف. الماء ينزلق: رفع القدم قبل المنعطف، والحذر من الضفة، والاستفادة من التيار والحلقات. في الفردي: ضد الساعة وأشباح الأصدقاء.',
