  '{n} voltas': 'عدد اللفات: {n}',
  'A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega.': 'الطاقة هي الحياة والتوربو معًا: الاصطدام بالحافة يستهلكها، والشريط الوردي يعيد شحنها.',
  'A nave explodiu: a energia acabou.': 'انفجرت المركبة: نفدت الطاقة.',
  'Posição: {posicao} de {total}': 'المركز: {posicao} من {total}',
  'Escolher a pista': 'اختيار المضمار',
  'Corrida de naves-cenoura numa pista suspensa, muito mais rápida que o kart. A energia é a vida e o turbo: bater na borda gasta, a faixa cor-de-rosa recarrega, e sair da pista é cair. No Solo, contra o relógio e os fantasmas dos amigos.': 'سباق مركبات على شكل جزر فوق مضمار معلّق، أسرع بكثير من الكارت. الطاقة هي الحياة والتوربو معًا: الاصطدام بالحافة يستهلكها، والشريط الوردي يعيد شحنها، والخروج من المضمار يعني السقوط. في الوضع الفردي: سباق ضد الساعة وضد أشباح الأصدقاء.',
  'Os karts numa arena fechada, cada um com três balões. Pegue as caixas e use os itens para estourar os balões dos outros: quem fica sem balão sai, e ganha quem sobrar.': 'عربات الكارت في حلبة مغلقة، ولكلٍّ منها ثلاثة بالونات. الهدف جمع الصناديق واستخدام الأدوات لتفجير بالونات الآخرين: من يبقى بلا بالونات يخرج، والفوز لمن يصمد حتى النهاية.',
  'Esquadrilha da toca': 'سرب الجحر',
  'Aviõezinhos de cenoura contra a praga da horta: desvie das sementes, pegue os reforços e derrube o espantalho mecânico no fim. A turma voa as mesmas ondas, e a esquadrilha soma os pontos.': 'طائرات جزر صغيرة في مواجهة آفات الحديقة: تفادي البذور، والتقاط الإمدادات، وإسقاط الفزّاعة الآلية في النهاية. تطير المجموعة في الموجات نفسها، وتُجمع نقاط السرب.',
  'O espantalho caiu!': 'سقطت الفزّاعة!',
