  'Seus navios': 'سفنك',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'يُرجى اختيار سفينة ثم لمس البحر. السحب لتغيير مكانها.',
  'Sortear a frota': 'توزيع عشوائي للأسطول',
  'Sua frota já está pronta.': 'أسطولك جاهز بالفعل.',
  'Ponha todos os navios antes.': 'يجب وضع كل السفن أولًا.',
  'Escolha um navio.': 'يُرجى اختيار سفينة.',
  'O navio não cabe aí.': 'السفينة لا تتسع هناك.',
  'Os navios não podem encostar um no outro.': 'لا يمكن أن تتلامس السفن.',
  'Minigolfe 3D': 'غولف مصغّر 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'ثماني حفر 3D، فيها منحدرات وقلعة وطاحونة هواء، والجميع يلعبون الحفرة نفسها في الوقت نفسه. السحب للتصويب وتحديد القوة، ثم الإفلات. الفوز لصاحب أقل مجموع من الضربات.',
  'Ver o buraco de cima': 'عرض الحفرة من الأعلى',
  'Fora da pista! Mais uma tacada.': 'خارج المسار! ضربة إضافية.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'السحب إلى الجانب للتصويب وإلى الأسفل للقوة، ثم الإفلات. بلوحة المفاتيح: الأسهم للتصويب، والضغط المستمر على مفتاح المسافة يحدد القوة.',
  'Futebol dos coelhos': 'كرة قدم الأرانب',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'كرة قدم في ملعب صغير، من الأعلى. لمس الكرة لقيادتها، والضغط المستمر على مفتاح المسافة لتسديد أقوى، والتمرير بـX. في الغرفة، تكتمل الفرق بروبوتات.',
  'Quantos por time?': 'كم لاعبًا في كل فريق؟',
  'Seu time venceu!': 'فاز فريقك!',
  'Seu time perdeu.': 'خسر فريقك.',
  'Passe': 'تمرير',
  'Chutar': 'تسديد',
  'Chutar (segure para mais força)': 'تسديد (الضغط المستمر لقوة أكبر)',
  'Gol!': 'هدف!',
  'Gol contra': 'هدف عكسي',
  'Partida inválida.': 'مباراة غير صالحة.',
  'Ninguém para jogar.': 'لا يوجد أحد للعب.',
  'Caça às pragas da horta': 'صيد آفات الحديقة',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'الغربان والجراد تهاجم الحديقة. التصويب والنقر لإصابتها قبل أن تهرب: الذخيرة محدودة، وكل موجة أسرع من سابقتها. يفوز صاحب أعلى النقاط.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'التصويب والنقر على الآفات قبل أن تهرب. كل طلقة تستهلك جزرة.',
