  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'تُسحب الكرة إلى الخلف ثم تُفلت. بلوحة المفاتيح: الأسهم للتصويب، والضغط المستمر على مفتاح المسافة يحدد القوة.',
  'Na água! Mais uma tacada.': 'في الماء! ضربة إضافية.',
  'No buraco!': 'في الحفرة!',
  'Acabaram as tacadas.': 'نفدت الضربات.',
  'Para a esquerda': 'إلى اليسار',
  'Para a direita': 'إلى اليمين',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'الأسهم للجري، ومفتاح المسافة للقفز (الضغط المستمر لقفزة أعلى).',
  'Nenhum amigo jogou esta fase ainda.': 'لم يلعب أي صديق هذه المرحلة بعد.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'مطر على البستان: الجميع يحصلون على {n} من الجزر.',
  '{nome} achou {n} cenouras escondidas.': 'عثور {nome} على {n} من الجزر المخبأ.',
  '{nome} trocou de lugar com {outro}.': 'تبادل الأماكن بين {nome} و{outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'لم يكتمل العدد: انتهت المباراة قبل وقتها، بلا كؤوس.',
  'Saiu antes do fim': 'مغادرة قبل النهاية',
  'Jogar o dado': 'رمي النرد',
  '{nome} comprou a cenoura dourada!': 'الجزرة الذهبية من نصيب {nome}!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'شراء الجزرة الذهبية مقابل {preco} من الجزر؟',
  'Comprar': 'شراء',
  '{nome} chegou à cenoura dourada.': 'وصول {nome} إلى الجزرة الذهبية.',
  'Quantas rodadas?': 'كم عدد الجولات؟',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'تدافع الأرانب عن البستان ضد الثعالب والغربان وغرير. المطلوب: التقدّم معًا، والضرب بالكومبو، وحماية بعضكم بعضًا: من 1 إلى 4 أشخاص.',
  'Pulo do coelho': 'قفزة الأرنب',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'سباق منصّات: جري وقفز ودون سقوط. فرديًا، ضد الساعة وأشباح الأصدقاء؛ ومع الجماعة، مباشرةً، في مرحلة واحدة أو في الثلاث.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'المطلوب تبديل خضارين متجاورين لجمع ثلاث قطع متطابقة أو أكثر. الكومة ترتفع بلا توقف، ويجب ألّا تصل إلى القمة. ومع الجماعة، ترسل السلاسل والكومبو صناديق إلى الآخرين.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'ست حفر للغولف المصغّر، والجميع يلعبون الحفرة نفسها في الوقت نفسه. تُسحب الكرة إلى الخلف ثم تُفلت للضرب. الفوز لصاحب أقل مجموع من الضربات.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'يُرمى النرد بالدور، ويتقدّم كل لاعب في البستان. يُجمع الجزر لشراء الجزرة الذهبية، وبعد كل جولة تلعب الجماعة لعبة مصغّرة. الفوز لصاحب أكبر عدد من الجزر الذهبي.',
