  'O fundo não é de uma cor só, e ficou como veio.': 'الخلفية ليست بلون واحد، فتُركت كما هي.',
  'No app do Syden, o recorte funciona com qualquer fundo.': 'في تطبيق Syden، تعمل إزالة الخلفية مع أي خلفية.',
