  'Crie figurinhas com as suas imagens, ou salve as que receber numa conversa.':
    'يمكنك إنشاء ملصقات من صورك، أو حفظ ما يصلك منها في محادثة.',
  'Dominó': 'دومينو',
  'Truco': 'تروكو',
  'Damas': 'الداما',
  'Batalha naval': 'معركة السفن',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'الدومينو المعتاد، من 2 إلى 4 لاعبين (مع 4، في فريقين من اثنين). تُوصَل القطع من الأطراف، ومن ينهي قطعه أولًا يأخذ نقاط ما في أيدي الآخرين.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'تروكو ساو باولو، بالورقة المكشوفة (فيرا) والأوراق الرابحة (مانيلا)، بلاعبَين أو بفريقين من اثنين. يمكن طلب التروكو، والرفع إلى ستة وتسعة واثني عشر، أو الانسحاب. الفوز لمن يحرز 12 نقطة.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'الداما البرازيلية: الأكل إلزامي، إلى الأمام وإلى الخلف، والملك يتحرك على القطر كاملًا. الغرفة تشاهد.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'كل لاعب يخفي أسطوله ويطلق النار على بحر الآخر. الإصابة تعني طلقة أخرى. الفوز لمن يُغرق الأسطول كاملًا أولًا. الغرفة تشاهد.',
