  'Cozinha da toca': 'مطبخ الجُحر',
  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': 'خذ المكونات من الصناديق، وقطّعها على اللوح، واطبخها على الموقد وفي الفرن دون أن تحترق، ورتّبها في الطبق وسلّمها من النافذة. يحصل الجميع على الطلبات نفسها: يفوز من يسلّم أكثر الأطباق في 3 دقائق.',
  'Pegar ou largar': 'التقاط أو وضع',
  'Este jogo precisa de gráficos 3D, que não abriram neste aparelho.': 'تحتاج هذه اللعبة إلى رسومات ثلاثية الأبعاد لم تعمل على هذا الجهاز.',
