  "Registros limitados de Docker, SSH, logind e kernel dos três boots mais recentes. Podem conter endereços IP.": "سجلات محدودة من Docker وSSH وlogind والنواة لآخر ثلاث عمليات إقلاع. قد تتضمن عناوين IP.",
  "Atualizar diagnóstico": "تحديث التشخيص",
  "Ainda não há snapshot. Ele será coletado na próxima abertura do cofre.": "لا توجد لقطة بعد. ستُجمع عند فتح الخزنة في المرة القادمة.",
