  'Para quando a escolha automática errar: a resolução e os quadros ficam os que você escolher, do começo ao fim da transmissão.': "عندما يخطئ الاختيار التلقائي: تبقى الدقة والإطارات كما اختيرت، من بداية البث إلى نهايته.",
  // O Syden Broadcast (16/11/2026)
  'Os efeitos de voz e de câmera feitos no seu computador, sem enviar nada a um servidor.': "مؤثرات الصوت والكاميرا التي تعمل على الجهاز، دون إرسال أي شيء إلى خادم.",
  // O Comando Cenoura (16/11/2026)
  'Comando Cenoura': "كوماندوز الجزر",
  'Correr e atirar com a turma: o lança-cenouras mira em oito direções, a granada abre caminho e quem solta os coelhinhos presos ganha reforço. O dragão espera no fim: de 1 a 4 pessoas.': "الجري وإطلاق النار مع المجموعة: قاذف الجزر يصوّب في ثمانية اتجاهات، والقنبلة تفتح الطريق، ومن يحرّر الأرانب الصغيرة المحبوسة ينال تعزيزًا. التنين ينتظر في النهاية: من 1 إلى 4 أشخاص.",
  'Andar e mirar': "المشي والتصويب",
  'Granada': "القنبلة اليدوية",
  // A Masmorra da Toca (16/11/2026)
  'Masmorra da Toca': "زنزانة الجُحر",
  'Atravessem juntos a toca do rei-cogumelo: salas cheias de bichos, um baú com a cenoura que vai e volta, botões que pedem dois ao mesmo tempo e a porta trancada. De 1 a 4 pessoas.': "عبور جماعي لجُحر ملك الفطر: غرف مليئة بالمخلوقات، وصندوق فيه الجزرة التي تذهب وتعود، وأزرار تحتاج إلى اثنين في وقت واحد، والباب المقفل. من 1 إلى 4 أشخاص.",
  // O Ringue da Toca (16/11/2026)
  'Ringue da Toca': "حلبة الجحر",
  'Boxe de reflexo contra três adversários do computador. Leia o aviso de cada golpe, esquive ou defenda e bata na brecha. Bater quando a luva brilha enche a estrela do soco forte.': "ملاكمة ردود فعل ضد ثلاثة خصوم من الحاسوب. قراءة إنذار كل ضربة، ثم المراوغة أو الصد، والضرب في الثغرة. الضرب عند لمعان القفاز يملأ نجمة اللكمة القوية.",
  'Esquivar': "مراوغة",
  'Abaixar e defender': "انحناء وصد",
  'Socar': "لكم",
  'Soco forte': "لكمة قوية",
  'Aperte os socos para levantar!': "للنهوض: الضغط على أزرار اللكم!",
  'Lutas vencidas: {n}': "النزالات الفائزة: {n}",
  'Nocaute!': "ضربة قاضية!",
  // A Rota Estelar (16/11/2026)
  'Rota Estelar': "الطريق النجمي",
  'Coelhos em naves pela superfície de um planeta e pelo espaço: atire, segure o tiro para travar a mira, gire para desviar dos tiros e escolha o caminho na bifurcação. A turma voa a mesma rota, e o chefe espera no fim.': "أرانب في سفن فضائية فوق سطح كوكب ثم في الفضاء: إطلاق النار، والضغط المستمر لتثبيت التصويب، والدوران لصدّ الطلقات، واختيار الطريق عند التفرّع. المجموعة تطير في الطريق نفسه، والزعيم ينتظر في النهاية.",
  'Pirueta': "دوران",
  'Segure para travar a mira': "ضغط مستمر لتثبيت التصويب",
  // O Pinball da Horta (16/11/2026)
  'Pinball da Horta': "بينبول البستان",
  'Uma mesa de pinball na horta: segure a mola, rebata nos repolhos e derrube as três cenouras para acender a toca do coelho, que solta mais uma bola. Três bolas, e sacudir demais trava a mesa.': "طاولة بينبول في البستان: سحب النابض، والارتداد عن الكرنب، وإسقاط الجزرات الثلاث لإضاءة جحر الأرنب الذي يُطلق كرة إضافية. ثلاث كرات، والهزّ الزائد يُقفل الطاولة.",
