  'Um RPG de turnos curto: cada um controla um herói da turma. Escolham juntos, combinem ataques e vençam o dragão do castelo.': "لعبة أدوار قصيرة بنظام الأدوار: كل لاعب يتحكم في بطل من الفريق. الاختيار معًا، ودمج الهجمات، والانتصار على تنين القلعة.",
