  "A largada precisa de uma reta.": "خط الانطلاق يحتاج إلى مقطع مستقيم.",
  "A Maravilha de {nome} ficou de pé por 2 minutos.": "صمدت أعجوبة {nome} دقيقتين.",
  "A mesma posição pela terceira vez empata, e 20 lances só de dama sem comer também.": "تكرار الوضع نفسه للمرة الثالثة تعادل، وكذلك 20 نقلة بالملوك وحدها دون أكل.",
  "À noite, veja quem os lobisomens atacaram. Uma poção salva essa pessoa e outra tira alguém do jogo; cada uma vale uma vez.": "في الليل، تظهر الضحية التي هاجمها المستذئبون. جرعة تنقذ هذا الشخص وأخرى تُخرج أحدًا من اللعبة؛ ولكل منهما مرة واحدة.",
  "A partida se desencontrou entre os computadores e foi encerrada.": "اختلّت المباراة بين الأجهزة وأُنهيت.",
  "A pedra que termina o lance na última fileira vira dama, que anda a diagonal inteira.": "الحجر الذي ينهي النقلة في الصف الأخير يصبح ملكًا، ويتحرك على القطر كله.",
