  "Vocês derrubaram os dois centros da vila da outra equipe.": "هدم فريقك مركزَي القرية للفريق الآخر.",
  // Os mini-games e as insígnias (19/11/2026)
  "A cidade que ninguém compra vai a leilão. Hipotecar uma cidade dá dinheiro, mas ela não cobra aluguel.": "المدينة التي لا يشتريها أحد تُعرض في المزاد. رهن المدينة يجلب المال، لكنها لا تجمع الإيجار.",
  "A dica acende a peça que move. O problema com dica não pontua; na corrida, ela tira 10 segundos.": "التلميح يُضيء القطعة التي تتحرك. المسألة التي يُستخدم فيها التلميح لا تُحتسب لها نقاط؛ وفي السباق، يُخصم بسببه 10 ثوانٍ.",
  "A manilha é o valor seguinte ao da vira e ganha de todas. Entre elas: ouros, espadas, copas e paus, o zap.": "المانيلا هي القيمة التالية لقيمة الفيرا، وتغلب كل الأوراق. وفيما بينها: الديناري، ثم البستوني، ثم الكبة، ثم السباتي، وهو الزاب.",
  "A última nave de cada volta sai.": "تخرج آخر مركبة في كل لفة.",
  "Abaixar": "انحناء",
  "Acertos em sequência: {n}": "إجابات صحيحة متتالية: {n}",
  "Ande pelo dado e compre a capital onde parar. Quem para na cidade de outro paga aluguel.": "التقدّم بحسب النرد، وشراء العاصمة عند التوقف فيها. ومن يتوقف في مدينة لاعب آخر يدفع الإيجار.",
  "Cada linha, coluna e bloco de 3 × 3 tem os números de 1 a 9, sem repetir.": "في كل صف وعمود ومربع 3 × 3 الأرقام من 1 إلى 9، دون تكرار.",
  "Cada um recebe 3 cartas. Leva a mão quem ganhar 2 das 3 rodadas.": "يحصل كل لاعب على 3 أوراق. وتذهب اليد لمن يفوز بجولتين من 3.",
  "Campeonato": "بطولة",
  "Com 11 pontos, a dupla vê as cartas e decide se joga a mão de onze. Vence quem chegar a 12.": "عند 11 نقطة، يرى الفريق أوراقه ويقرر لعب يد الأحد عشر أو لا. الفوز لمن يصل إلى 12.",
  "Com a região inteira, construa até 4 prédios: o aluguel sobe a cada um.": "بامتلاك المنطقة كاملة، يمكن بناء حتى 4 مبانٍ: يرتفع الإيجار مع كل مبنى.",
  "Com estrelas, o soco forte (★) gasta todas de uma vez e dói mais.": "مع النجوم، تستهلك اللكمة القوية (★) النجوم كلها دفعة واحدة وتؤلم أكثر.",
  "Dica": "تلميح",
  "Dica: este problema não pontua": "تلميح: هذه المسألة لا تُحتسب لها نقاط",
  "Dica: tira 10 segundos": "تلميح: يُخصم 10 ثوانٍ",
  "Eliminação": "إقصاء",
  "Encoste uma pedra numa ponta da mesa com o mesmo número.": "توصيل قطعة بطرف على الطاولة يحمل الرقم نفسه.",
  "Escolha a casa e depois o número. O lápis anota só para você.": "اختيار المربع ثم الرقم. ملاحظات القلم الرصاص لا يراها أحد غيرك.",
  "Esquive do golpe e soque logo depois: é o contra-ataque, e vale estrela.": "المراوغة من الضربة ثم اللكم فورًا: هذا هو الهجوم المضاد، ويمنح نجمة.",
  "Fora da corrida na volta {n}.": "الخروج من السباق في اللفة {n}.",
  "Força das cartas": "قوة الأوراق",
  "Ganha o maior patrimônio no fim das rodadas, ou quem sobrar.": "الفوز لصاحب أكبر ثروة في نهاية الجولات، أو لآخر من يبقى.",
  "Iniciante": "مبتدئ",
  "Mestre": "أستاذ",
  "Na sequência, cada acerto traz um problema mais difícil, e o primeiro erro acaba.": "في وضع السلسلة، كل إجابة صحيحة تأتي بمسألة أصعب، وأول خطأ يُنهي اللعب.",
  "O número pequeno no botão diz quantos ainda faltam.": "الرقم الصغير على الزر يبيّن كم تبقّى منه.",
  "Os cinco traçados seguidos contra o computador, com pontos.": "المسارات الخمسة متتالية ضد الحاسوب، مع النقاط.",
  "Peça truco e a mão vale 3. Quem responde aceita, corre ou aumenta para 6, 9 ou 12.": "عند طلب التروكو تصبح قيمة اليد 3. ومن يُطلب منه يقبل أو ينسحب أو يرفع إلى 6 أو 9 أو 12.",
  "Quem bate fica sem pedras e leva os pontos das mãos dos outros. Trancado, leva quem tem menos pontos na mão.": "من يُنهي قطعه يأخذ نقاط ما في أيدي الآخرين. وإذا انغلق اللعب، يفوز صاحب أقل النقاط في يده.",
  "Sem pedra que sirva, compre. Sem nada para comprar, a vez passa.": "إن لم تكن هناك قطعة مناسبة، يُسحب من الكومة. وإن لم يبقَ شيء للسحب، ينتقل الدور.",
