  "Na variante sem comer para trás, a pedra só come para a frente; a dama continua comendo para todo lado.": "في النسخة بلا أكل إلى الخلف، الحجر يأكل إلى الأمام فقط؛ والملك يواصل الأكل في كل الاتجاهات.",
