  "No mineiro não há vira: as manilhas são o 4 de paus, o 7 de copas, o ás de espadas e o 7 de ouros.": "في مينيرو لا توجد ورقة مكشوفة: المانيلات هي 4 السباتي و7 الكبة وآص البستوني و7 الديناري.",
  "No mineiro, a mão vale 2, e o truco, o seis, o nove e o doze valem 4, 8, 10 e 12. Com 10 pontos, é a mão de dez: jogar valendo 4, ou correr e dar 2.": "في مينيرو، اليد بقيمة 2، والتروكو والستة والتسعة والاثنا عشر بقيمة 4 و8 و10 و12. مع 10 نقاط تكون يد العشرة: اللعب بقيمة 4، أم الانسحاب ومنح 2.",
