  "Saara": "الصحراء الكبرى",
  "Sai um animal secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a classe, a dieta, onde ele vive e o peso. Quem acertar com menos chutes ganha mais pontos.": "يُختار حيوان سري، ويخمّن كل لاعب حيوانات أخرى. يُظهر كل تخمين ما يطابق السري: الصنف، والنظام الغذائي، ومكان عيشه، والوزن. من يصيب بتخمينات أقل ينال نقاطًا أكثر.",
  "Sai um dinossauro secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: o período, a dieta, o grupo, o comprimento e onde ele foi achado. Quem acertar com menos chutes ganha mais pontos.": "يُختار ديناصور سري، ويخمّن كل لاعب ديناصورات أخرى. يُظهر كل تخمين ما يطابق السري: الحقبة، والنظام الغذائي، والمجموعة، والطول، ومكان العثور عليه. من يصيب بتخمينات أقل ينال نقاطًا أكثر.",
  "Sai um elemento químico secreto, e cada um chuta outros. Cada chute mostra o que bate com o secreto: a família, o estado físico, o período, o grupo e o número atômico. Quem acertar com menos chutes ganha mais pontos.": "يُختار عنصر كيميائي سري، ويخمّن كل لاعب عناصر أخرى. يُظهر كل تخمين ما يطابق السري: العائلة، والحالة الفيزيائية، والدورة، والمجموعة، والعدد الذري. من يصيب بتخمينات أقل ينال نقاطًا أكثر.",
  "Sai um estado secreto do Brasil, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a população, a área, o litoral e a fronteira com outro país. Quem acertar com menos chutes ganha mais pontos.": "تُختار ولاية سرية من البرازيل، ويخمّن كل لاعب ولايات أخرى. يُظهر كل تخمين المسافة والاتجاه إلى السرية، والمنطقة، والسكان، والمساحة، والساحل، والحدود مع دولة أخرى. من يصيب بتخمينات أقل ينال نقاطًا أكثر.",
  "Saturno": "زحل",
