  "{pessoa} sai da comunidade e das chamadas dela na hora, e só volta se alguém que administra desbanir.": "يتمّ إخراج {pessoa} من المجتمع ومن مكالماته فورًا، ولا تكون العودة ممكنة إلا إذا ألغت الإدارة الحظر.",
  "Quem administra esta comunidade baniu a sua conta, e por isso não dá para entrar.": "حظرت إدارة هذا المجتمع هذا الحساب، ولذلك لا يمكن الدخول.",
